def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    bob_eric_high = False
    david_bid = None
    active_threat = 0.0

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            bid = float(bid)
            prev_bids.append(bid)
            if oid in ('Bob', 'Eric') and bid >= 95:
                bob_eric_high = True
            if oid == 'David':
                david_bid = bid
            if bid > active_threat:
                active_threat = bid

    low_supply = supply <= 17.0
    high_supply = supply >= 22.0
    urgent = hp <= 4 or no_water >= 2
    semi_urgent = hp <= 6 or no_water >= 1

    if urgent:
        if high_supply:
            bid = 92.0
        elif low_supply:
            bid = 108.0
        else:
            bid = 98.0
        if david_bid is not None:
            bid = max(bid, david_bid + 3.0)
        return float(min(budget, bid))

    if low_supply and bob_eric_high and hp >= 7 and no_water == 0:
        return float(min(budget, 8.0))

    if high_supply:
        base = 44.0
        if david_bid is not None:
            base = max(base, david_bid + 2.0)
        elif active_threat > 0:
            base = max(base, min(65.0, active_threat * 0.6))
        if semi_urgent:
            base += 10.0
        return float(min(budget, base))

    base = 52.0
    if david_bid is not None:
        base = max(base, david_bid + 3.0)
    elif active_threat > 0:
        if active_threat >= 95.0 and hp >= 7:
            base = 18.0
        else:
            base = max(base, min(72.0, active_threat + 2.0))

    if semi_urgent:
        base += 12.0
    if day >= 8 and hp <= 6:
        base += 10.0

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = 70.0 * (8 - day) * 0.15
    bid = min(budget, base)
    if budget - bid < reserve_floor and not semi_urgent:
        bid = max(0.0, budget - reserve_floor)

    return float(max(0.0, min(budget, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = int(day_context['supply'])
    day = int(day_context['day'])
    hp = int(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    alive_opponents = [o for o in opponents_status.values() if o.get('alive', False)]
    if not alive_opponents:
        # Only me left, bid minimal
        return min(budget, 0.4 * DAILY_SALARY)

    # Collect yesterday's bids from alive opponents
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(float(prev['bid']))

    # Determine base need: low HP or no water -> need water urgently
    urgent = (hp <= 2) or (no_water_days >= 1)

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # Bob-like aggressive bidder
        if highest_prev >= 0.85 * DAILY_SALARY:
            if urgent:
                # Must win: outbid slightly above highest
                return min(budget, highest_prev + 2.0)
            else:
                # Don't engage, bid low
                return min(budget, 0.3 * DAILY_SALARY)
        else:
            # Moderate competition: bid just above highest to secure if needed
            if urgent:
                return min(budget, max(0.6 * DAILY_SALARY, highest_prev + 1.5))
            else:
                return min(budget, max(0.4 * DAILY_SALARY, highest_prev + 0.5))
    else:
        # No yesterday info: fallback
        if urgent:
            return min(budget, 0.85 * DAILY_SALARY)
        else:
            return min(budget, 0.5 * DAILY_SALARY)
